from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    counts=Counter(v for row in g for v in row)
    bg=counts.most_common(1)[0][0]
    border_counts=Counter(g[r][c] for r in range(h) for c in range(w) if (r in (0,h-1) or c in (0,w-1)) and g[r][c]!=bg)
    source=border_counts.most_common(1)[0][0]
    marker_colors=[v for v in counts if v not in (bg,source)]
    if not marker_colors: return g
    ray=marker_colors[0]
    # Find maximal runs on each orientation, from the selected border source color.
    hruns=[]
    for r in (0,h-1):
        c=0
        while c<w:
            if g[r][c]==source:
                s=c
                while c<w and g[r][c]==source: c+=1
                if c-s>=2: hruns.append((r,s,c-1))
            else: c+=1
    vruns=[]
    for c in (0,w-1):
        r=0
        while r<h:
            if g[r][c]==source:
                s=r
                while r<h and g[r][c]==source: r+=1
                if r-s>=2: vruns.append((c,s,r-1))
            else: r+=1
    hmax=max((b-a+1 for r,a,b in hruns),default=0)
    vmax=max((b-a+1 for c,a,b in vruns),default=0)
    horizontal=hmax>vmax
    if horizontal:
        parity={r0%2 for r0 in range(h) for c0 in range(w) if g[r0][c0]==ray}
        for r,s,e in hruns:
            dr=1 if r==0 else -1
            for c in range(s,e+1):
                if c%2 not in parity: continue
                rr=r+dr
                while 0<=rr<h:
                    if g[rr][c]==ray:
                        g[rr][c]=4; break
                    if g[rr][c]!=bg: break
                    g[rr][c]=ray
                    rr+=dr
    else:
        parity={c0%2 for r0 in range(h) for c0 in range(w) if g[r0][c0]==ray}
        for c,s,e in vruns:
            dc=1 if c==0 else -1
            for r in range(s,e+1):
                if r%2 not in parity: continue
                cc=c+dc
                while 0<=cc<w:
                    if g[r][cc]==ray:
                        g[r][cc]=4; break
                    if g[r][cc]!=bg: break
                    g[r][cc]=ray
                    cc+=dc
    return g

